import{c as d,Q as r,j as e,m as a}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"SIMD API列表","description":"","frontmatter":{},"headers":[{"level":1,"title":"SIMD API列表","slug":"simd-api列表"},{"level":2,"title":"基础数据结构","slug":"基础数据结构"},{"level":2,"title":"基础API","slug":"基础api"},{"level":2,"title":"高阶API","slug":"高阶api"}],"relativePath":"api/SIMD-API/SIMD-API列表.md","filePath":"api/SIMD-API/SIMD-API列表.md"}'),o={name:"api/SIMD-API/SIMD-API列表.md"};function s(l,t,n,i,c,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="simd-api列表" tabindex="-1">SIMD API列表 <a class="header-anchor" href="#simd-api列表" aria-label="Permalink to &quot;SIMD API列表&quot;">​</a></h1><h2 id="基础数据结构" tabindex="-1">基础数据结构 <a class="header-anchor" href="#基础数据结构" aria-label="Permalink to &quot;基础数据结构&quot;">​</a></h2><p><strong>表 1</strong> 基础数据结构列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>LocalTensor</td><td>LocalTensor用于存放AI Core中Local Memory（内部存储）的数据，支持逻辑位置TPosition为VECIN、VECOUT、VECCALC、A1、A2、B1、B2、CO1、CO2。</td></tr><tr><td>GlobalTensor</td><td>GlobalTensor用来存放Global Memory（外部存储）的全局数据。</td></tr><tr><td>Coordinate</td><td>Coordinate本质上是一个元组（tuple），用于表示张量在不同维度的位置信息，即坐标值。</td></tr><tr><td>Layout</td><td>Layout&lt;Shape, Stride&gt;数据结构是描述多维张量内存布局的基础模板类，通过编译时的形状（Shape）和步长（Stride）信息，实现逻辑坐标空间到一维内存地址空间的映射，为复杂张量操作和硬件优化提供基础支持。</td></tr><tr><td>TensorTrait</td><td>TensorTrait数据结构是描述Tensor相关信息的基础模板类，包含Tensor的数据类型、逻辑位置和Layout内存布局。</td></tr></tbody></table><h2 id="基础api" tabindex="-1">基础API <a class="header-anchor" href="#基础api" aria-label="Permalink to &quot;基础API&quot;">​</a></h2><p><strong>表 2</strong> Memory数据搬运API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>DataCopy</td><td>数据搬运接口，包括普通数据搬运、增强数据搬运、切片数据搬运、随路格式转换。</td></tr><tr><td>Copy</td><td>VECIN、VECCALC、VECOUT之间的搬运指令，支持mask操作和DataBlock间隔操作。</td></tr></tbody></table><p><strong>表 3</strong> Memory矢量计算API列表</p><table tabindex="0"><thead><tr><th>分类</th><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>基础算术</td><td>Exp</td><td>按元素取自然指数。</td></tr><tr><td>基础算术</td><td>Ln</td><td>按元素取自然对数。</td></tr><tr><td>基础算术</td><td>Abs</td><td>按元素取绝对值。</td></tr><tr><td>基础算术</td><td>Reciprocal</td><td>按元素取倒数。</td></tr><tr><td>基础算术</td><td>Sqrt</td><td>按元素做开方。</td></tr><tr><td>基础算术</td><td>Rsqrt</td><td>按元素做开方后取倒数。</td></tr><tr><td>基础算术</td><td>Relu</td><td>按元素做线性整流Relu。</td></tr><tr><td>基础算术</td><td>Add</td><td>按元素求和。</td></tr><tr><td>基础算术</td><td>Sub</td><td>按元素求差。</td></tr><tr><td>基础算术</td><td>Mul</td><td>按元素求积。</td></tr><tr><td>基础算术</td><td>Div</td><td>按元素求商。</td></tr><tr><td>基础算术</td><td>Max</td><td>按元素求最大值。</td></tr><tr><td>基础算术</td><td>Min</td><td>按元素求最小值。</td></tr><tr><td>基础算术</td><td>Adds</td><td>矢量内每个元素与标量求和。</td></tr><tr><td>基础算术</td><td>Muls</td><td>矢量内每个元素与标量求积。</td></tr><tr><td>基础算术</td><td>Maxs</td><td>源操作数矢量内每个元素与标量相比，如果比标量大，则取源操作数值，比标量的值小，则取标量值。</td></tr><tr><td>基础算术</td><td>Mins</td><td>源操作数矢量内每个元素与标量相比，如果比标量大，则取标量值，比标量的值小，则取源操作数值。</td></tr><tr><td>基础算术</td><td>LeakyRelu</td><td>按元素做带泄露线性整流Leaky ReLU。</td></tr><tr><td>基础算术</td><td>Subs</td><td>矢量内每个元素和标量间做减法，支持标量在前和标量在后两种场景，其中标量输入支持配置LocalTensor单点元素。</td></tr><tr><td>基础算术</td><td>Divs</td><td>矢量内每个元素和标量间做除法，支持标量在前和标量在后两种场景，其中标量输入支持配置LocalTensor单点元素。</td></tr><tr><td>逻辑计算</td><td>Not</td><td>按元素做按位取反。</td></tr><tr><td>逻辑计算</td><td>And</td><td>针对每对元素执行按位与运算。</td></tr><tr><td>逻辑计算</td><td>Or</td><td>针对每对元素执行按位或运算。</td></tr><tr><td>逻辑计算</td><td>ShiftLeft</td><td>对源操作数中的每个元素进行左移操作，左移的位数由输入参数scalarValue决定。</td></tr><tr><td>逻辑计算</td><td>ShiftRight</td><td>对源操作数中的每个元素进行右移操作，右移的位数由输入参数scalarValue决定。</td></tr><tr><td>逻辑计算</td><td>Ands</td><td>矢量内每个元素和标量间做与操作，支持标量在前和标量在后两种场景，其中标量输入支持配置LocalTensor单点元素。</td></tr><tr><td>逻辑计算</td><td>Ors</td><td>矢量内每个元素和标量间做或操作，支持标量在前和标量在后两种场景，其中标量输入支持配置LocalTensor单点元素。</td></tr><tr><td>复合计算</td><td>Axpy</td><td>源操作数中每个元素与标量求积后和目的操作数中的对应元素相加。</td></tr><tr><td>复合计算</td><td>CastDequant</td><td>对输入做量化并进行精度转换。</td></tr><tr><td>复合计算</td><td>AddRelu</td><td>按元素求和，结果和0对比取较大值。</td></tr><tr><td>复合计算</td><td>AddReluCast</td><td>按元素求和，结果和0对比取较大值，并根据源操作数和目的操作数Tensor的数据类型进行精度转换。</td></tr><tr><td>复合计算</td><td>AddDeqRelu</td><td>依次计算按元素求和、结果进行deq量化后再进行relu计算（结果和0对比取较大值）。</td></tr><tr><td>复合计算</td><td>SubRelu</td><td>按元素求差，结果和0对比取较大值。</td></tr><tr><td>复合计算</td><td>SubReluCast</td><td>按元素求差，结果和0对比取较大值，并根据源操作数和目的操作数Tensor的数据类型进行精度转换。</td></tr><tr><td>复合计算</td><td>MulAddDst</td><td>按元素将src0Local和src1Local相乘并和dstLocal相加，将最终结果存放进dstLocal中。</td></tr><tr><td>复合计算</td><td>MulCast</td><td>按元素求积，并根据源操作数和目的操作数Tensor的数据类型进行精度转换。</td></tr><tr><td>复合计算</td><td>FusedMulAdd</td><td>按元素将src0Local和dstLocal相乘并加上src1Local，最终结果存放入dstLocal。</td></tr><tr><td>复合计算</td><td>MulAddRelu</td><td>按元素将src0Local和dstLocal相乘并加上src1Local，将结果和0作比较，取较大值，最终结果存放进dstLocal中。</td></tr><tr><td>比较与选择</td><td>Compare</td><td>逐元素比较两个tensor大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。</td></tr><tr><td>比较与选择</td><td>Compare（结果存放入寄存器）</td><td>逐元素比较两个tensor大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。Compare接口需要mask参数时，可以使用此接口。计算结果存放入寄存器中。</td></tr><tr><td>比较与选择</td><td>Compares</td><td>逐元素比较一个tensor中的元素和另一个Scalar的大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。</td></tr><tr><td>比较与选择</td><td>Select</td><td>给定两个源操作数src0和src1，根据selMask（用于选择的Mask掩码）的比特位值选取元素，得到目的操作数dst。选择的规则为：当selMask的比特位是1时，从src0中选取，比特位是0时从src1选取。</td></tr><tr><td>比较与选择</td><td>GatherMask</td><td>以内置固定模式对应的二进制或者用户自定义输入的Tensor数值对应的二进制为gather mask（数据收集的掩码），从源操作数中选取元素写入目的操作数中。</td></tr><tr><td>精度转换指令</td><td>Cast</td><td>根据源操作数和目的操作数Tensor的数据类型进行精度转换。</td></tr><tr><td>归约计算</td><td>ReduceMax</td><td>在所有的输入数据中找出最大值及最大值对应的索引位置。</td></tr><tr><td>归约计算</td><td>ReduceMin</td><td>在所有的输入数据中找出最小值及最小值对应的索引位置。</td></tr><tr><td>归约计算</td><td>ReduceSum</td><td>对所有的输入数据求和。</td></tr><tr><td>归约计算</td><td>WholeReduceMax</td><td>每个repeat内所有数据求最大值以及其索引index。</td></tr><tr><td>归约计算</td><td>WholeReduceMin</td><td>每个repeat内所有数据求最小值以及其索引index。</td></tr><tr><td>归约计算</td><td>WholeReduceSum</td><td>每个repeat内所有数据求和。</td></tr><tr><td>归约计算</td><td>BlockReduceMax</td><td>对每个repeat内所有元素求最大值。</td></tr><tr><td>归约计算</td><td>BlockReduceMin</td><td>对每个repeat内所有元素求最小值。</td></tr><tr><td>归约计算</td><td>BlockReduceSum</td><td>对每个repeat内所有元素求和。源操作数相加采用二叉树方式，两两相加。</td></tr><tr><td>归约计算</td><td>PairReduceSum</td><td>PairReduceSum：相邻两个（奇偶）元素求和。</td></tr><tr><td>归约计算</td><td>RepeatReduceSum</td><td>每个repeat内所有数据求和。和WholeReduceSum接口相比，不支持mask逐bit模式。建议使用功能更全面的WholeReduceSum接口。</td></tr><tr><td>数据转换</td><td>Transpose</td><td>可实现16*16的二维矩阵数据块的转置和[N,C,H,W]与[N,H,W,C]互相转换。</td></tr><tr><td>数据转换</td><td>TransDataTo5HD</td><td>数据格式转换，一般用于将NCHW格式转换成NC1HWC0格式。特别的，也可以用于二维矩阵数据块的转置。</td></tr><tr><td>数据填充</td><td>Duplicate</td><td>将一个变量或一个立即数，复制多次并填充到向量。</td></tr><tr><td>数据填充</td><td>Brcb</td><td>给定一个输入张量，每一次取输入张量中的8个数填充到结果张量的8个datablock（32Bytes）中去，每个数对应一个datablock。</td></tr><tr><td>数据填充</td><td>CreateVecIndex</td><td>以firstValue为起始值创建向量索引。</td></tr><tr><td>数据分散/数据收集</td><td>Gather</td><td>给定输入的张量和一个地址偏移张量，Gather指令根据偏移地址将输入张量按元素收集到结果张量中。</td></tr><tr><td>掩码操作</td><td>SetMaskCount</td><td>设置mask模式为Counter模式。该模式下，不需要开发者去感知迭代次数、处理非对齐的尾块等操作，可直接传入计算数据量，实际迭代次数由Vector计算单元自动推断。</td></tr><tr><td>掩码操作</td><td>SetMaskNorm</td><td>设置mask模式为Normal模式。该模式为系统默认模式，支持开发者配置迭代次数。</td></tr><tr><td>掩码操作</td><td>SetVectorMask</td><td>用于在矢量计算时设置mask。</td></tr><tr><td>掩码操作</td><td>ResetMask</td><td>恢复mask的值为默认值（全1），表示矢量计算中每次迭代内的所有元素都将参与运算。</td></tr><tr><td>量化设置</td><td>SetDeqScale</td><td>设置DEQSCALE寄存器的值。</td></tr></tbody></table><p><strong>表 4</strong> 标量计算API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>GetBitCount</td><td>获取一个uint64_t类型数字的二进制中0或者1的个数。</td></tr><tr><td>CountLeadingZero</td><td>计算一个uint64_t类型数字前导0的个数（二进制从最高位到第一个1一共有多少个0）。</td></tr><tr><td>Cast（float转half、int32_t）</td><td>将一个scalar的类型转换为指定的类型。</td></tr><tr><td>CountBitsCntSameAsSignBit</td><td>计算一个uint64_t类型数字的二进制中，从最高数值位开始与符号位相同的连续比特位的个数。</td></tr><tr><td>GetSFFValue</td><td>获取一个uint64_t类型数字的二进制中第一个0或1出现的位置。</td></tr><tr><td>Cast（float转bfloat16_t）</td><td>float类型标量数据转换成bfloat16_t类型标量数据。</td></tr><tr><td>Cast（多类型转float）</td><td>bfloat16_t类型标量数据转换成float类型标量数据。</td></tr></tbody></table><p><strong>表 5</strong> 资源管理API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>TPipe</td><td>TPipe是用来管理全局内存等资源的框架。通过TPipe类提供的接口可以完成内存等资源的分配管理操作。</td></tr><tr><td>GetTPipePtr</td><td>获取框架当前管理全局内存的TPipe指针，用户获取指针后，可进行TPipe相关的操作。</td></tr><tr><td>TBufPool</td><td>TPipe可以管理全局内存资源，而TBufPool可以手动管理或复用Unified Buffer/L1 Buffer物理内存，主要用于多个stage计算中Unified Buffer/L1 Buffer物理内存不足的场景。</td></tr><tr><td>TQue</td><td>提供入队出队等接口，通过队列（Queue）完成任务间同步。</td></tr><tr><td>TQueBind</td><td>TQueBind绑定源逻辑位置和目的逻辑位置，根据源位置和目的位置，来确定内存分配的位置 、插入对应的同步事件，帮助开发者解决内存分配和管理、同步等问题。</td></tr><tr><td>TBuf</td><td>使用Ascend C编程的过程中，可能会用到一些临时变量。这些临时变量占用的内存可以使用TBuf数据结构来管理。</td></tr><tr><td>InitSpmBuffer</td><td>初始化SPM Buffer。</td></tr><tr><td>WriteSpmBuffer</td><td>将需要溢出暂存的数据拷贝到SPM Buffer中。</td></tr><tr><td>ReadSpmBuffer</td><td>从SPM Buffer读回到local数据中。</td></tr><tr><td>GetUserWorkspace</td><td>获取用户使用的workspace指针。</td></tr><tr><td>SetSysWorkSpace</td><td>在进行融合算子编程时，由于框架通信机制需要使用到workspace，也就是系统workspace，所以在该场景下，开发者要调用该接口，设置系统workspace的指针。</td></tr><tr><td>GetSysWorkSpacePtr</td><td>获取系统workspace指针。</td></tr></tbody></table><p><strong>表 6</strong> 同步控制API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>TQueSync</td><td>TQueSync类提供同步控制接口，开发者可以使用这类API来自行完成同步控制。</td></tr><tr><td>IBSet</td><td>当不同核之间操作同一块全局内存且可能存在读后写、写后读以及写后写等数据依赖问题时，通过调用该函数来插入同步语句来避免上述数据依赖时可能出现的数据读写错误问题。调用IBSet设置某一个核的标志位，与IBWait成对出现配合使用，表示核之间的同步等待指令，等待某一个核操作完成。</td></tr><tr><td>IBWait</td><td>当不同核之间操作同一块全局内存且可能存在读后写、写后读以及写后写等数据依赖问题时，通过调用该函数来插入同步语句来避免上述数据依赖时可能出现的数据读写错误问题。IBWait与IBSet成对出现配合使用，表示核之间的同步等待指令，等待某一个核操作完成。</td></tr><tr><td>SyncAll</td><td>当不同核之间操作同一块全局内存且可能存在读后写、写后读以及写后写等数据依赖问题时，通过调用该函数来插入同步语句来避免上述数据依赖时可能出现的数据读写错误问题。目前多核同步分为硬同步和软同步，硬件同步是利用硬件自带的全核同步指令由硬件保证多核同步，软件同步是使用软件算法模拟实现。</td></tr><tr><td>InitDetermineComputeWorkspace</td><td>初始化GM共享内存的值，完成初始化后才可以调用WaitPreBlock和NotifyNextBlock。</td></tr><tr><td>WaitPreBlock</td><td>通过读GM地址中的值，确认是否需要继续等待，当GM的值满足当前核的等待条件时，该核即可往下执行，进行下一步操作。</td></tr><tr><td>NotifyNextBlock</td><td>通过写GM地址，通知下一个核当前核的操作已完成，下一个核可以进行操作。</td></tr><tr><td>SetNextTaskStart</td><td>在SuperKernel的子Kernel中调用，调用后的指令可以和后续其他的子Kernel实现并行，提升整体性能。</td></tr><tr><td>WaitPreTaskEnd</td><td>在SuperKernel的子Kernel中调用，调用前的指令可以和前序其他的子Kernel实现并行，提升整体性能。</td></tr></tbody></table><p><strong>表 7</strong> 缓存处理API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>DataCachePreload</td><td>从源地址所在的特定DDR地址预加载数据到data cache中。</td></tr><tr><td>DataCacheCleanAndInvalid</td><td>该接口用来刷新Cache，保证Cache的一致性。</td></tr></tbody></table><p><strong>表 8</strong> 系统变量访问API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>GetBlockNum</td><td>获取当前任务配置的Block数，用于代码内部的多核逻辑控制等。</td></tr><tr><td>GetBlockIdx</td><td>获取当前core的index，用于代码内部的多核逻辑控制及多核偏移量计算等。</td></tr><tr><td>GetDataBlockSizeInBytes</td><td>获取当前芯片版本一个datablock的大小，单位为byte。开发者根据datablock的大小来计算API指令中待传入的repeatTime 、DataBlock Stride、Repeat Stride等参数值。</td></tr><tr><td>GetArchVersion</td><td>获取当前AI处理器架构版本号。</td></tr><tr><td>InitSocState</td><td>由于AI Core上存在一些全局状态，如原子累加状态、Mask模式等，在实际运行中，这些值可以被前序执行的算子修改而导致计算出现不符合预期的行为，在静态Tensor编程的场景中用户必须在Kernel入口处调用此函数来初始化AI Core状态 。</td></tr></tbody></table><p><strong>表 9</strong> 原子操作接口列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>SetAtomicAdd</td><td>设置接下来从VECOUT到GM，L0C到GM，L1到GM的数据传输是否进行原子累加，可根据参数不同设定不同的累加数据类型。</td></tr><tr><td>SetAtomicType</td><td>通过设置模板参数来设定原子操作不同的数据类型。</td></tr><tr><td>DisableDmaAtomic</td><td>原子操作函数，清空原子操作的状态。</td></tr><tr><td>AtomicAdd</td><td>调用该接口后，可在指定GM地址上进行原子加操作。</td></tr><tr><td>AtomicMin</td><td>调用该接口后，可在指定GM地址上进行原子比较取小操作。</td></tr><tr><td>AtomicMax</td><td>调用该接口后，可在指定GM地址上进行原子取大操作。</td></tr><tr><td>AtomicCas</td><td>调用该接口后，可在指定GM地址上进行原子比较，如果和value1相等，则把value2的值赋值到GM上；如果和value1不相等，则GM上的值不变。</td></tr><tr><td>AtomicExch</td><td>在GM内存中执行原子交换操作。具体来说，它读取指定GM地址上的数据，并将新的值存储回同一地址。函数返回旧值。</td></tr></tbody></table><p><strong>表 10</strong> 调试接口列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>DumpTensor</td><td>基于算子工程开发的算子，可以使用该接口Dump指定Tensor的内容。</td></tr><tr><td>printf</td><td>基于算子工程开发的算子，可以使用该接口实现CPU侧/NPU侧调试场景下的格式化输出功能。</td></tr><tr><td>ascendc_assert</td><td>ascendc_assert提供了一种在CPU/NPU域实现断言功能的接口。当断言条件不满足时，系统会输出断言信息并格式化打印在屏幕上。</td></tr><tr><td>assert</td><td>基于算子工程开发的算子，可以使用该接口实现CPU/NPU域assert断言功能。</td></tr><tr><td>DumpAccChkPoint</td><td>基于算子工程开发的算子，可以使用该接口Dump指定Tensor的内容。该接口可以支持指定偏移位置的Tensor打印。</td></tr><tr><td>PrintTimeStamp</td><td>提供时间戳打点功能，用于在算子Kernel代码中标记关键执行点。</td></tr><tr><td>Trap</td><td>当软件产生异常后，使用该指令使kernel中止运行。</td></tr><tr><td>GmAlloc</td><td>进行核函数的CPU侧运行验证时，用于创建共享内存：在/tmp目录下创建一个共享文件，并返回该文件的映射指针。</td></tr><tr><td>ICPU_RUN_KF</td><td>进行核函数的CPU侧运行验证时，CPU调测总入口，完成CPU侧的算子程序调用。</td></tr><tr><td>ICPU_SET_TILING_KEY</td><td>用于指定本次CPU调测使用的tilingKey。调测执行时，将只执行算子核函数中该tilingKey对应的分支。</td></tr><tr><td>GmFree</td><td>进行核函数的CPU侧运行验证时，用于释放通过GmAlloc申请的共享内存。</td></tr><tr><td>SetKernelMode</td><td>CPU调测时，设置内核模式为单AIV模式，单AIC模式或者MIX模式，以分别支持单AIV矢量算子，单AIC矩阵算子，MIX混合算子的CPU调试。</td></tr><tr><td>TRACE_START</td><td>通过CAModel进行算子性能仿真时，可对算子任意运行阶段打点，从而分析不同指令的流水图，以便进一步性能调优。 用于表示起始位置打点，一般与TRACE_STOP配套使用。</td></tr><tr><td>TRACE_STOP</td><td>通过CAModel进行算子性能仿真时，可对算子任意运行阶段打点，从而分析不同指令的流水图，以便进一步性能调优。 用于表示终止位置打点，一般与TRACE_START配套使用。</td></tr><tr><td>MetricsProfStart</td><td>用于设置性能数据采集信号启动，和MetricsProfStop配合使用。使用工具进行算子上板调优时，可在kernel侧代码段前后分别调用MetricsProfStart和MetricsProfStop来指定需要调优的代码段范围。</td></tr><tr><td>MetricsProfStop</td><td>设置性能数据采集信号停止，和MetricsProfStart配合使用。使用工具进行算子上板调优时，可在kernel侧代码段前后分别调用MetricsProfStart和MetricsProfStop来指定需要调优的代码段范围。</td></tr></tbody></table><p><strong>表 11</strong> 工具函数接口列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Async</td><td>Async提供了一个统一的接口，用于在不同模式下（AIC或AIV）执行特定函数，从而避免代码中直接的硬件条件判断（如使用ASCEND_IS_AIV或ASCEND_IS_AIC）。</td></tr><tr><td>NumericLimits</td><td>NumericLimits工具类，用于查询指定数据类型的最大值/最小值等属性。</td></tr><tr><td>GetTaskRatio</td><td>适用于Cube/Vector分离模式，用来获取Cube/Vector的配比。</td></tr><tr><td>GetUBSizeInBytes</td><td>获取UB空间的大小，单位为byte。</td></tr><tr><td>GetRuntimeUBSize</td><td>获取运行时UB空间的大小，单位为byte。开发者根据UB的大小来计算循环次数等参数值。</td></tr></tbody></table><p><strong>表 12</strong> Kernel Tiling接口列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>GET_TILING_DATA</td><td>用于获取算子kernel入口函数传入的tiling信息，并填入注册的Tiling结构体中，此函数会以宏展开的方式进行编译。如果用户注册了多个TilingData结构体，使用该接口返回默认注册的结构体。</td></tr><tr><td>GET_TILING_DATA_WITH_STRUCT</td><td>使用该接口指定结构体名称，可获取指定的tiling信息，并填入对应的Tiling结构体中，此函数会以宏展开的方式进行编译。</td></tr><tr><td>GET_TILING_DATA_MEMBER</td><td>用于获取tiling结构体的成员变量。</td></tr><tr><td>TILING_KEY_IS</td><td>在核函数中判断本次执行时的tiling_key是否等于某个key，从而标识tiling_key==key的一条kernel分支。</td></tr><tr><td>REGISTER_TILING_DEFAULT</td><td>用于在kernel侧注册用户使用标准C++语法自定义的默认TilingData结构体。</td></tr><tr><td>REGISTER_TILING_FOR_TILINGKEY</td><td>用于在kernel侧注册与TilingKey相匹配的TilingData自定义结构体；该接口需提供一个逻辑表达式，逻辑表达式以字符串“TILING_KEY_VAR”代指实际TilingKey，表达TIlingKey所满足的范围。</td></tr><tr><td>REGISTER_NONE_TILING</td><td>在Kernel侧使用标准C++语法自定义的TilingData结构体时，若用户不确定需要注册哪些结构体，可使用该接口告知框架侧需使用未注册的标准C++语法来定义TilingData，并配套GET_TILING_DATA_WITH_STRUCT，GET_TILING_DATA_MEMBER，GET_TILING_DATA_PTR_WITH_STRUCT来获取对应的TilingData。</td></tr><tr><td>KERNEL_TASK_TYPE_DEFAULT</td><td>设置全局默认的kernel type，对所有的tiling key生效。</td></tr><tr><td>KERNEL_TASK_TYPE</td><td>设置某一个具体的tiling key对应的kernel type。</td></tr></tbody></table><p><strong>表 13</strong> ISASI接口列表</p><table tabindex="0"><thead><tr><th>分类</th><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>标量计算</td><td>WriteGmByPassDCache</td><td>不经过DCache向GM地址上写数据。</td></tr><tr><td>标量计算</td><td>ReadGmByPassDCache</td><td>不经过DCache从GM地址上读数据。</td></tr><tr><td>矢量计算</td><td>VectorPadding</td><td>根据padMode（pad模式）与padSide（pad方向）对源操作数按照datablock进行填充操作。</td></tr><tr><td>矢量计算</td><td>BilinearInterpolation</td><td>双线性插值操作，分为垂直迭代和水平迭代。</td></tr><tr><td>矢量计算</td><td>GetCmpMask</td><td>获取Compare（结果存入寄存器）指令的比较结果。</td></tr><tr><td>矢量计算</td><td>SetCmpMask</td><td>为Select不传入mask参数的接口设置比较寄存器。</td></tr><tr><td>矢量计算</td><td>GetReduceRepeatSumSpr</td><td>获取ReduceSum（针对tensor前n个数据计算）接口的计算结果。</td></tr><tr><td>矢量计算</td><td>GetReduceRepeatMaxMinSpr</td><td>获取ReduceMax、ReduceMin连续场景下的最大/最小值以及相应的索引值。</td></tr><tr><td>矢量计算</td><td>ProposalConcat</td><td>将连续元素合入Region Proposal内对应位置，每次迭代会将16个连续元素合入到16个Region Proposals的对应位置里。</td></tr><tr><td>矢量计算</td><td>ProposalExtract</td><td>与ProposalConcat功能相反，从Region Proposals内将相应位置的单个元素抽取后重排，每次迭代处理16个Region Proposals，抽取16个元素后连续排列。</td></tr><tr><td>矢量计算</td><td>RpSort16</td><td>根据Region Proposals中的score域对其进行排序（score大的排前面），每次排16个Region Proposals。</td></tr><tr><td>矢量计算</td><td>MrgSort4</td><td>将已经排好序的最多4 条region proposals队列，排列并合并成1条队列，结果按照score域由大到小排序。</td></tr><tr><td>矢量计算</td><td>Sort32</td><td>排序函数，一次迭代可以完成32个数的排序。</td></tr><tr><td>矢量计算</td><td>MrgSort</td><td>将已经排好序的最多4 条队列，合并排列成 1 条队列，结果按照score域由大到小排序。</td></tr><tr><td>矢量计算</td><td>GetMrgSortResult</td><td>获取MrgSort或MrgSort4已经处理过的队列里的Region Proposal个数，并依次存储在四个List入参中。</td></tr><tr><td>矢量计算</td><td>Gatherb</td><td>给定一个输入的张量和一个地址偏移张量，Gatherb指令根据偏移地址将输入张量收集到结果张量中。</td></tr><tr><td>矢量计算</td><td>Scatter</td><td>给定一个连续的输入张量和一个目的地址偏移张量，Scatter指令根据偏移地址生成新的结果张量后将输入张量分散到结果张量中。</td></tr><tr><td>矢量计算</td><td>Prelu</td><td>源操作数src0大于0的情况下直接将src0写入目的操作数dst，否则将源操作数src0 * src1的结果写入dst。</td></tr><tr><td>矢量计算</td><td>Mull</td><td>对前count个输入数据src0、src1按元素相乘操作，将结果写入dst0Local，溢出部分写入dst1Local。</td></tr><tr><td>矢量计算</td><td>AbsSub</td><td>将src0Local与src1相减再求绝对值， 并将计算结果写入dst。</td></tr><tr><td>矢量计算</td><td>ExpSub</td><td>src0与src1相减，将差值作为指数计算自然常数e的幂次， 并将计算结果写入dst。</td></tr><tr><td>矢量计算</td><td>MulsCast</td><td>将矢量源操作数前count个数据与标量相乘再按照CAST_ROUND模式转换成half类型， 并将计算结果写入dst，此接口支持标量在前和标量在后两种场景。</td></tr><tr><td>矢量计算</td><td>Truncate</td><td>将源操作数的浮点数元素截断到整数位，同时源操作数的数据类型保持不变。</td></tr><tr><td>矢量计算</td><td>Interleave</td><td>给定源操作数src0和src1，将src0和src1中的元素交织存入结果操作数dst0和dst1中。</td></tr><tr><td>矢量计算</td><td>DeInterleave</td><td>给定源操作数src0和src1，将src0和src1中的元素解交织存入结果操作数dst0和dst1中。</td></tr><tr><td>数据搬运</td><td>DataCopyPad</td><td>该接口提供数据非对齐搬运的功能。</td></tr><tr><td>数据搬运</td><td>SetPadValue</td><td>设置DataCopyPad接口填充的数值。</td></tr><tr><td>矩阵计算</td><td>Mmad</td><td>完成矩阵乘加操作。</td></tr><tr><td>矩阵计算</td><td>MmadWithSparse</td><td>完成矩阵乘加操作，传入的左矩阵A为稀疏矩阵， 右矩阵B为稠密矩阵 。</td></tr><tr><td>矩阵计算</td><td>SetHF32Mode</td><td>此接口同SetHF32TransMode、SetMMRowMajor以及SetMMColumnMajor一样，都用于设置寄存器的值。SetHF32Mode接口用于设置MMAD的HF32模式。</td></tr><tr><td>矩阵计算</td><td>SetHF32TransMode</td><td>此接口同SetHF32Mode、SetMMRowMajor以及SetMMColumnMajor一样，都用于设置寄存器的值。SetHF32TransMode用于设置MMAD的HF32取整模式，仅在MMAD的HF32模式生效时有效。</td></tr><tr><td>矩阵计算</td><td>SetMMRowMajor</td><td>此接口同SetHF32Mode、SetHF32TransMode一样，都用于设置寄存器的值，本接口用于设置MMAD计算时优先通过N方向。</td></tr><tr><td>矩阵计算</td><td>SetMMColumnMajor</td><td>此接口同SetHF32Mode、SetHF32TransMode一样，都用于设置寄存器的值，本接口用于设置MMAD计算时优先通过M方向。</td></tr><tr><td>矩阵计算</td><td>Conv2D</td><td>计算给定输入张量和权重张量的2-D卷积，输出结果张量。Conv2d卷积层多用于图像识别，使用过滤器提取图像中的特征。</td></tr><tr><td>矩阵计算</td><td>Gemm</td><td>根据输入的切分规则，将给定的两个输入张量做矩阵乘，输出至结果张量。将A和B两个输入矩阵乘法在一起，得到一个输出矩阵C。</td></tr><tr><td>矩阵计算</td><td>SetFixPipeConfig</td><td>DataCopy（CO1-&gt;GM、CO1-&gt;A1）过程中进行随路量化时，通过调用该接口设置量化流程中tensor量化参数。</td></tr><tr><td>矩阵计算</td><td>SetFixpipeNz2ndFlag</td><td>DataCopy（CO1-&gt;GM、CO1-&gt;A1）过程中进行随路格式转换（NZ2ND）时，通过调用该接口设置NZ2ND相关配置。</td></tr><tr><td>矩阵计算</td><td>SetFixpipePreQuantFlag</td><td>DataCopy（CO1-&gt;GM、CO1-&gt;A1）过程中进行随路量化时，通过调用该接口设置量化流程中scalar量化参数。</td></tr><tr><td>矩阵计算</td><td>SetFixPipeClipRelu</td><td>DataCopy（CO1-&gt;GM）过程中进行随路量化后，通过调用该接口设置ClipRelu操作的最大值。</td></tr><tr><td>矩阵计算</td><td>SetFixPipeAddr</td><td>DataCopy（CO1-&gt;GM）过程中进行随路量化后，通过调用该接口设置element-wise操作时LocalTensor的地址。</td></tr><tr><td>矩阵计算</td><td>Fill</td><td>初始化LocalTensor（TPosition为A1/A2/B1/B2）为某一个具体的数值。</td></tr><tr><td>矩阵计算</td><td>LoadData</td><td>LoadData包括Load2D和Load3D数据加载功能。</td></tr><tr><td>矩阵计算</td><td>LoadDataWithTranspose</td><td>该接口实现带转置的2D格式数据从A1/B1到A2/B2的加载。</td></tr><tr><td>矩阵计算</td><td>SetAippFunctions</td><td>设置图片预处理（AIPP，AI core pre-process）相关参数。</td></tr><tr><td>矩阵计算</td><td>LoadImageToLocal</td><td>将图像数据从GM搬运到A1/B1。 搬运过程中可以完成图像预处理操作：包括图像翻转，改变图像尺寸（抠图，裁边，缩放，伸展），以及色域转换，类型转换等。</td></tr><tr><td>矩阵计算</td><td>LoadUnZipIndex</td><td>加载GM上的压缩索引表到内部寄存器。</td></tr><tr><td>矩阵计算</td><td>LoadDataUnzip</td><td>将GM上的数据解压并搬运到A1/B1/B2上。</td></tr><tr><td>矩阵计算</td><td>LoadDataWithSparse</td><td>用于搬运存放在B1里的512B的稠密权重矩阵到B2里，同时读取128B的索引矩阵用于稠密矩阵的稀疏化。</td></tr><tr><td>矩阵计算</td><td>SetFmatrix</td><td>用于调用Load3Dv1/Load3Dv2时设置FeatureMap的属性描述。</td></tr><tr><td>矩阵计算</td><td>SetLoadDataBoundary</td><td>设置Load3D时A1/B1边界值。</td></tr><tr><td>矩阵计算</td><td>SetLoadDataRepeat</td><td>用于设置Load3Dv2接口的repeat参数。设置repeat参数后，可以通过调用一次Load3Dv2接口完成多个迭代的数据搬运。</td></tr><tr><td>矩阵计算</td><td>SetLoadDataPaddingValue</td><td>设置padValue，用于Load3Dv1/Load3Dv2。</td></tr><tr><td>矩阵计算</td><td>Fixpipe</td><td>矩阵计算完成后，对结果进行处理，例如对计算结果进行量化操作，并把数据从CO1搬迁到Global Memory中。</td></tr><tr><td>同步控制</td><td>SetFlag/WaitFlag</td><td>同一核内不同流水线之间的同步指令。具有数据依赖的不同流水指令之间需要插此同步。</td></tr><tr><td>同步控制</td><td>PipeBarrier</td><td>阻塞相同流水，具有数据依赖的相同流水之间需要插此同步。</td></tr><tr><td>同步控制</td><td>DataSyncBarrier</td><td>用于阻塞后续的指令执行，直到所有之前的内存访问指令（需要等待的内存位置可通过参数控制）执行结束。</td></tr><tr><td>同步控制</td><td>CrossCoreSetFlag</td><td>针对分离模式，AI Core上的Cube核（AIC）与Vector核（AIV）之间的同步设置指令。</td></tr><tr><td>同步控制</td><td>CrossCoreWaitFlag</td><td>针对分离模式，AI Core上的Cube核（AIC）与Vector核（AIV）之间的同步等待指令。</td></tr><tr><td>同步控制</td><td>Mutex</td><td>Mutex用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖。每个锁有固定的一个MutexID，该ID可通过用户自定义（范围为0-27）或者通过AllocMutexID/ReleaseMutexID进行申请释放。</td></tr><tr><td>同步控制</td><td>AllocMutexID</td><td>从框架获取并占用一个MutexID，与ReleaseMutexID配合使用，管理MutexID的获取和释放。</td></tr><tr><td>同步控制</td><td>ReleaseMutexID</td><td>从框架释放一个MutexID，与AllocMutexID配合使用。</td></tr><tr><td>缓存处理</td><td>ICachePreLoad</td><td>从指令所在DDR地址预加载指令到ICache中。</td></tr><tr><td>缓存处理</td><td>GetICachePreloadStatus</td><td>获取ICACHE的PreLoad的状态。</td></tr><tr><td>系统变量访问</td><td>GetProgramCounter</td><td>获取程序计数器的指针，程序计数器用于记录当前程序执行的位置。</td></tr><tr><td>系统变量访问</td><td>GetSubBlockNum</td><td>获取AI Core上Vector核的数量。</td></tr><tr><td>系统变量访问</td><td>GetSubBlockIdx</td><td>获取AI Core上Vector核的ID。</td></tr><tr><td>系统变量访问</td><td>GetSystemCycle</td><td>获取当前系统cycle数，若换算成时间需要按照50MHz的频率，时间单位为us，换算公式为：time = (cycle数/50) us 。</td></tr><tr><td>系统变量访问</td><td>SetCtrlSpr</td><td>对CTRL寄存器（控制寄存器）的特定比特位进行设置。</td></tr><tr><td>系统变量访问</td><td>GetCtrlSpr</td><td>读取CTRL寄存器（控制寄存器）特定比特位上的值。</td></tr><tr><td>系统变量访问</td><td>ResetCtrlSpr</td><td>对CTRL寄存器（控制寄存器）的特定比特位做重置。</td></tr><tr><td>原子操作</td><td>SetAtomicMax</td><td>原子操作函数，设置后续从VECOUT传输到GM的数据是否执行原子比较，将待拷贝的内容和GM已有内容进行比较，将最大值写入GM。</td></tr><tr><td>原子操作</td><td>SetAtomicMin</td><td>原子操作函数，设置后续从VECOUT传输到GM的数据是否执行原子比较，将待拷贝的内容和GM已有内容进行比较，将最小值写入GM。</td></tr><tr><td>原子操作</td><td>SetStoreAtomicConfig</td><td>设置原子操作使能位与原子操作类型。</td></tr><tr><td>原子操作</td><td>GetStoreAtomicConfig</td><td>获取原子操作使能位与原子操作类型的值。</td></tr><tr><td>调试接口</td><td>CheckLocalMemoryIA</td><td>监视设定范围内的UB读写行为，如果监视到有设定范围的读写行为则会出现EXCEPTION报错，未监视到设定范围的读写行为则不会报错。</td></tr><tr><td>Cube分组管理</td><td>CubeResGroupHandle</td><td>CubeResGroupHandle用于在分离模式下通过软同步控制AIC和AIV之间进行通讯，实现AI Core计算资源分组。</td></tr><tr><td>Cube分组管理</td><td>GroupBarrier</td><td>当同一个CubeResGroupHandle中的两个AIV任务之间存在依赖关系时，可以使用GroupBarrier控制同步。</td></tr><tr><td>Cube分组管理</td><td>KfcWorkspace</td><td>KfcWorkspace为通信空间描述符，管理不同CubeResGroupHandle的消息通信区划分，与CubeResGroupHandle配合使用。KfcWorkspace的构造函数用于创建KfcWorkspace对象。</td></tr></tbody></table><h2 id="高阶api" tabindex="-1">高阶API <a class="header-anchor" href="#高阶api" aria-label="Permalink to &quot;高阶API&quot;">​</a></h2><p><strong>表 14</strong> 数学计算API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Acos</td><td>按元素做反余弦函数计算。</td></tr><tr><td>Acosh</td><td>按元素做双曲反余弦函数计算。</td></tr><tr><td>Asin</td><td>按元素做反正弦函数计算。</td></tr><tr><td>Asinh</td><td>按元素做反双曲正弦函数计算。</td></tr><tr><td>Atan</td><td>按元素做三角函数反正切运算。</td></tr><tr><td>Atanh</td><td>按元素做反双曲正切余弦函数计算。</td></tr><tr><td>Axpy</td><td>源操作数中每个元素与标量求积后和目的操作数中的对应元素相加。</td></tr><tr><td>Ceil</td><td>获取大于或等于x的最小的整数值，即向正无穷取整操作。</td></tr><tr><td>ClampMax</td><td>将srcTensor中大于scalar的数替换为scalar，小于等于scalar的数保持不变，作为dstTensor输出。</td></tr><tr><td>ClampMin</td><td>将srcTensor中小于scalar的数替换为scalar，大于等于scalar的数保持不变，作为dstTensor输出。</td></tr><tr><td>Cos</td><td>按元素做三角函数余弦运算。</td></tr><tr><td>Cosh</td><td>按元素做双曲余弦函数计算。</td></tr><tr><td>CumSum</td><td>对数据按行依次累加或按列依次累加。</td></tr><tr><td>Digamma</td><td>按元素计算x的gamma函数的对数导数。</td></tr><tr><td>Erf</td><td>按元素做误差函数计算，也称为高斯误差函数。</td></tr><tr><td>Erfc</td><td>返回输入x的互补误差函数结果，积分区间为x到无穷大。</td></tr><tr><td>Exp</td><td>按元素取自然指数。</td></tr><tr><td>Floor</td><td>获取小于或等于x的最小的整数值，即向负无穷取整操作。</td></tr><tr><td>Fmod</td><td>按元素计算两个浮点数相除后的余数。</td></tr><tr><td>Frac</td><td>按元素做取小数计算。</td></tr><tr><td>Hypot</td><td>按元素计算两个浮点数平方和的平方根。</td></tr><tr><td>IsFinite</td><td>按元素判断输入的浮点数是否非NAN、非±INF。</td></tr><tr><td>Lgamma</td><td>按元素计算x的gamma函数的绝对值并求自然对数。</td></tr><tr><td>Log</td><td>按元素以e、2、10为底做对数运算。</td></tr><tr><td>Power</td><td>实现按元素做幂运算功能。</td></tr><tr><td>Round</td><td>将输入的元素四舍五入到最接近的整数。</td></tr><tr><td>Sign</td><td>按元素执行Sign操作，Sign是指返回输入数据的符号。</td></tr><tr><td>Sin</td><td>按元素做正弦函数计算。</td></tr><tr><td>Sinh</td><td>按元素做双曲正弦函数计算。</td></tr><tr><td>Tan</td><td>按元素做正切函数计算。</td></tr><tr><td>Tanh</td><td>按元素做逻辑回归Tanh。</td></tr><tr><td>Trunc</td><td>按元素做浮点数截断操作，即向零取整操作。</td></tr><tr><td>Xor</td><td>按元素执行Xor（异或）运算。</td></tr><tr><td>Fma</td><td>按元素计算两个输入相乘后与第三个输入相加的结果。</td></tr><tr><td>IsNan</td><td>按元素判断输入的浮点数是否为nan。</td></tr><tr><td>IsInf</td><td>按元素判断输入的浮点数是否为±INF。</td></tr><tr><td>Rint</td><td>获取与输入数据最接近的整数。</td></tr><tr><td>SinCos</td><td>按元素进行正弦计算和余弦计算，分别获得正弦和余弦的结果。</td></tr><tr><td>LogicalNot</td><td>按元素进行取反操作。</td></tr><tr><td>LogicalAnd</td><td>按元素进行与操作。</td></tr><tr><td>LogicalAnds</td><td>输入矢量内的每个元素与标量进行与操作。</td></tr><tr><td>LogicalOr</td><td>按元素进行或操作。</td></tr><tr><td>LogicalOrs</td><td>输入矢量内的每个元素与标量进行或操作。</td></tr><tr><td>LogicalXor</td><td>按元素进行逻辑异或操作。</td></tr><tr><td>BitwiseNot</td><td>逐比特对输入进行取反。</td></tr><tr><td>BitwiseAnd</td><td>逐比特对两个输入进行与操作。</td></tr><tr><td>BitwiseOr</td><td>逐比特对两个输入进行或操作。</td></tr><tr><td>BitwiseXor</td><td>逐比特对两个输入进行异或操作。</td></tr><tr><td>Where</td><td>根据指定的条件，从两个源操作数中选择元素，生成目标操作数。</td></tr></tbody></table><p><strong>表 15</strong> 量化操作API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>AntiQuantize</td><td>按元素做伪量化计算，比如将int8_t数据类型伪量化为half数据类型。</td></tr><tr><td>AscendAntiQuant</td><td>按元素做伪量化计算，比如将int8_t数据类型伪量化为half数据类型。</td></tr><tr><td>Dequantize</td><td>按元素做反量化计算，比如将int32_t数据类型反量化为half/float等数据类型。</td></tr><tr><td>AscendDequant</td><td>按元素做反量化计算，比如将int32_t数据类型反量化为half/float等数据类型。</td></tr><tr><td>Quantize</td><td>按元素做量化计算，比如将half/float数据类型量化为int8_t数据类型。</td></tr><tr><td>AscendQuant</td><td>按元素做量化计算，比如将half/float数据类型量化为int8_t数据类型。</td></tr></tbody></table><p><strong>表 16</strong> 归一化操作API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>BatchNorm</td><td>对于每个batch中的样本，对其输入的每个特征在batch的维度上进行归一化。</td></tr><tr><td>DeepNorm</td><td>在深层神经网络训练过程中，可以替代LayerNorm的一种归一化方法。</td></tr><tr><td>GroupNorm</td><td>将输入的C维度分为groupNum组，对每一组数据进行标准化。</td></tr><tr><td>LayerNorm</td><td>将输入数据收敛到[0, 1]之间，可以规范网络层输入输出数据分布的一种归一化方法。</td></tr><tr><td>LayerNormGrad</td><td>用于计算LayerNorm的反向传播梯度。</td></tr><tr><td>LayerNormGradBeta</td><td>用于获取反向beta/gmma的数值，和LayerNormGrad共同输出pdx, gmma和beta。</td></tr><tr><td>Normalize</td><td>LayerNorm中，已知均值和方差，计算shape为[A，R]的输入数据的标准差的倒数rstd和归一化输出y。</td></tr><tr><td>RmsNorm</td><td>实现对shape大小为[B，S，H]的输入数据的RmsNorm归一化。</td></tr><tr><td>WelfordUpdate</td><td>实现Welford算法的前处理。</td></tr><tr><td>WelfordFinalize</td><td>实现Welford算法的后处理。</td></tr></tbody></table><p><strong>表 17</strong> 激活函数API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>AdjustSoftMaxRes</td><td>用于对SoftMax相关计算结果做后处理，调整SoftMax的计算结果为指定的值。</td></tr><tr><td>FasterGelu</td><td>FastGelu化简版本的一种激活函数。</td></tr><tr><td>FasterGeluV2</td><td>实现FastGeluV2版本的一种激活函数。</td></tr><tr><td>GeGLU</td><td>采用GeLU作为激活函数的GLU变体。</td></tr><tr><td>Gelu</td><td>GELU是一个重要的激活函数，其灵感来源于relu和dropout，在激活中引入了随机正则的思想。</td></tr><tr><td>LogSoftMax</td><td>对输入tensor做LogSoftmax计算。</td></tr><tr><td>ReGlu</td><td>一种GLU变体，使用Relu作为激活函数。</td></tr><tr><td>Sigmoid</td><td>按元素做逻辑回归Sigmoid。</td></tr><tr><td>Silu</td><td>按元素做Silu运算。</td></tr><tr><td>SimpleSoftMax</td><td>使用计算好的sum和max数据对输入tensor做softmax计算。</td></tr><tr><td>SoftMax</td><td>对输入tensor按行做Softmax计算。</td></tr><tr><td>SoftmaxFlash</td><td>SoftMax增强版本，除了可以对输入tensor做softmaxflash计算，还可以根据上一次softmax计算的sum和max来更新本次的softmax计算结果。</td></tr><tr><td>SoftmaxFlashV2</td><td>SoftmaxFlash增强版本，对应FlashAttention-2算法。</td></tr><tr><td>SoftmaxFlashV3</td><td>SoftmaxFlash增强版本，对应Softmax PASA算法。</td></tr><tr><td>SoftmaxGrad</td><td>对输入tensor做grad反向计算的一种方法。</td></tr><tr><td>SoftmaxGradFront</td><td>对输入tensor做grad反向计算的一种方法。</td></tr><tr><td>SwiGLU</td><td>采用Swish作为激活函数的GLU变体。</td></tr><tr><td>Swish</td><td>神经网络中的Swish激活函数。</td></tr></tbody></table><p><strong>表 18</strong> 归约操作API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Sum</td><td>获取最后一个维度的元素总和。</td></tr><tr><td>Mean</td><td>根据最后一轴的方向对各元素求平均值。</td></tr><tr><td>ReduceXorSum</td><td>按照元素执行Xor（按位异或）运算，并将计算结果ReduceSum求和。</td></tr><tr><td>ReduceSum</td><td>对一个多维向量按照指定的维度进行数据累加。</td></tr><tr><td>ReduceMean</td><td>对一个多维向量按照指定的维度求平均值。</td></tr><tr><td>ReduceMax</td><td>对一个多维向量在指定的维度求最大值。</td></tr><tr><td>ReduceMin</td><td>对一个多维向量在指定的维度求最小值。</td></tr><tr><td>ReduceAny</td><td>对一个多维向量在指定的维度求逻辑或。</td></tr><tr><td>ReduceAll</td><td>对一个多维向量在指定的维度求逻辑与。</td></tr><tr><td>ReduceProd</td><td>对一个多维向量在指定的维度求积。</td></tr></tbody></table><p><strong>表 19</strong> 排序操作API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>TopK</td><td>获取最后一个维度的前k个最大值或最小值及其对应的索引。</td></tr><tr><td>Concat</td><td>对数据进行预处理，将要排序的源操作数srcLocal一一对应的合入目标数据concatLocal中，数据预处理完后，可以进行Sort。</td></tr><tr><td>Extract</td><td>处理Sort的结果数据，输出排序后的value和index。</td></tr><tr><td>Sort</td><td>排序函数，按照数值大小进行降序排序。</td></tr><tr><td>MrgSort</td><td>将已经排好序的最多4条队列，合并排列成1条队列，结果按照score域由大到小排序。</td></tr></tbody></table><p><strong>表 20</strong> 数据过滤API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Select</td><td>给定两个源操作数src0和src1，根据maskTensor相应位置的值（非bit位）选取元素，得到目的操作数dst。</td></tr><tr><td>DropOut</td><td>提供根据MaskTensor对源操作数进行过滤的功能，得到目的操作数。</td></tr></tbody></table><p><strong>表 21</strong> 张量变换API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Transpose</td><td>对输入数据进行数据排布及Reshape操作。</td></tr><tr><td>TransData</td><td>将输入数据的排布格式转换为目标排布格式。</td></tr><tr><td>Broadcast</td><td>将输入按照输出shape进行广播。</td></tr><tr><td>Pad</td><td>对height * width的二维Tensor在width方向上pad到32B对齐。</td></tr><tr><td>UnPad</td><td>对height * width的二维Tensor在width方向上进行unpad。</td></tr><tr><td>Fill</td><td>将Global Memory上的数据初始化为指定值。</td></tr></tbody></table><p><strong>表 22</strong> 索引计算API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Arange</td><td>给定起始值，等差值和长度，返回一个等差数列。</td></tr></tbody></table><p><strong>表 23</strong> 矩阵计算API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Matmul</td><td>Matmul矩阵乘法的运算。</td></tr></tbody></table><p><strong>表 24</strong> HCCL通信类API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>HCCL通信类</td><td>在AI Core侧编排集合通信任务。</td></tr></tbody></table><p><strong>表 25</strong> 卷积计算API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>Conv3D</td><td>3维卷积正向矩阵运算。</td></tr><tr><td>Conv3DBackpropInput</td><td>卷积的反向运算，求解特征矩阵的反向传播误差。</td></tr><tr><td>Conv3DBackpropFilter</td><td>卷积的反向运算，求解权重的反向传播误差。</td></tr></tbody></table><p><strong>表 26</strong> 随机函数API列表</p><table tabindex="0"><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td>PhiloxRandom</td><td>基于Philox随机数生成算法，给定随机数种子，生成若干的随机数。</td></tr></tbody></table>',56)])])}const S=d(o,[["render",s]]);export{u as __pageData,S as default};
